import { Vector3 } from '../shared/utils/vector3.js';
import { UnrealBloomPass } from '../shared/effects/unrealBloomPass.js';
import { PlayerShip } from './player.js';
import { EnemyRow } from './enemyRow.js';
import { ParticleManager } from '../particleManager.js';
import { VFXManager } from './vfxManager.js';
import { InputHandler } from '../input/dualInput.js';
import { Game } from './game.js';
import { Scene } from './scene.js';
import { Renderer } from './renderer.js';

// === CONFIGURATION ===
const WIDTH = 800;
const HEIGHT = 600;

// === INITIALIZATION ===
const scene = new Scene(WIDTH, HEIGHT);
const renderer = new Renderer(scene, WIDTH, HEIGHT);
const camera = scene.camera;
const player = new PlayerShip(camera);
const enemyRows = new EnemyRow(player, 10, 10); // 10 rows, 10 enemies per row
const particleManager = new ParticleManager(renderer);
const vfxManager = new VFXManager(renderer, camera);
const inputHandler = new InputHandler(player, enemyRows, particleManager);

// === GAME OBJECTS ===
const game = new Game(player, enemyRows, particleManager, vfxManager, renderer, camera, inputHandler);

// === EVENT BINDINGS ===
game.bindInput(inputHandler);
game.bindKeyboard(inputHandler);
game.bindGamepad(inputHandler);

// === GAME LOOP ===
function gameLoop() {
    const delta = game.getDelta();

    // Update game logic
    player.update(delta);
    enemyRows.update(delta);
    particleManager.update(delta);
    vfxManager.update(delta, player, enemyRows, particleManager);

    // Render
    renderer.render(delta);

    requestAnimationFrame(gameLoop);
}

// Start the game loop
gameLoop();
