```js
import { Vector3 } from '../shared/utils/vector3.js';
import { UnrealBloomPass } from '../shared/effects/unrealBloomPass.js';
import { PlayerShip } from './player.js';
import { EnemyRow } from './enemyRow.js';
import { ParticleManager } from '../particleManager.js';
import { VFXManager } from './vfxManager.js';

export class Game {
    constructor(player, enemyRows, particleManager, vfxManager, renderer, camera, inputHandler) {
        this.player = player;
        this.enemyRows = enemyRows;
        this.particleManager = particleManager;
        this.vfxManager = vfxManager;
        this.renderer = renderer;
        this.camera = camera;
        this.inputHandler = inputHandler;
        this.running = true;
        this.score = 0;
        this.lives = 3;
        this.gameOver = false;
        this.font = new Font('https://fonts.googleapis.com/css?family=Roboto&display=swap');
        this.fontSize = 24;
        this.healthText = null;

        // Game state
        this.state = 'PLAYING';
    }

    bindInput(inputHandler) {
        inputHandler.onKeyDown = (key, callback) => {
            if (this.state !== 'PLAYING') return;
            callback();
        };
        inputHandler.onKeyUp = (key, callback) => {
            if (this.state !== 'PLAYING') return;
            callback();
        };
        inputHandler.onGamepadButtonDown = (button, callback) => {
            if (this.state !== 'PLAYING') return;
            callback();
        };
        inputHandler.onGamepadButtonUp = (button, callback) => {
            if (this.state !== 'PLAYING') return;
            callback();
        };

        // Mouse for shooting
        this.renderer.canvas.addEventListener('mousedown', (e) => {
            if (!this.state || !this.player.shooting) return;
            this.inputHandler.fireBullet(this.player.position);
        });
    }

    update(delta) {
        if (!this.running) return;

        // Player movement
        const move = this.inputHandler.getKeyDown('w') ? 1 : 0;
        const moveLeft = this.inputHandler.getKeyDown('a') ? -1 : 0;
        const moveRight = this.inputHandler.getKeyDown('d') ? 1 : 0;
        const forward = this.inputHandler.isPressed('w') || this.inputHandler.isPressed('w');
        const backward = this.inputHandler.isPressed('s') ? -1 : 0;

        const vel = move * 2.5 + forward * 2.5 - moveLeft * 2.5 - moveRight * 2.5;
        this.player.position.x += vel * delta;
        this.player.position.z += (forward - backward) * delta;

        // Clamp player to field
        const maxX = this.renderer.canvas.width / 2 - this.player.size / 2;
        const minX = -maxX + this.player.size / 2;
        const maxZ = this.renderer.canvas.height / 2 - this.player.size / 2;
        const minZ = -maxZ + this.player.size / 2;
        this.player.position.x = Math.max(minX, Math.min(maxX, this.player.position.x));
        this.player.position.z = Math.max(minZ, Math.min(maxZ, this.player.position.z));

        // Shooting
        if (this.inputHandler.isPressed('space') && this.player.shooting) {
            this.inputHandler.fireBullet(this.player.position);
        }

        // Enemy movement
        this.enemyRows.update(delta);

        // Particle management
        this.particleManager.update(delta, this.player, this.enemyRows);

        // VFX updates
        this.vfxManager.update(delta, this.player, this.enemyRows, this.particleManager);

        // Collision handling
        this.checkCollisions();

        // Score & UI update
        if (this.state === 'PLAYING') {
            this.score += this.inputHandler.getBulletCount() * 10;
            this.updateUI();
        }

        // Game over check
        if (this.player.position.distanceTo(this.enemyRows.topRow[0].position) < this.player.size / 2 + this.enemyRows.topRow[0].size / 2) {
            this.gameOver = true;
            this.state = 'GAME_OVER';
        }
    }

    checkCollisions() {
        // Bullet vs Enemy
        this.particleManager.bullets.forEach((bullet, bIndex) => {
            this.enemyRows.forEach(row => row.enemies.forEach((enemy, eIndex) => {
                if (this.bulletIntersect(bullet, enemy)) {
                    bullet.dispose();
                    this.particleManager.burstBullet(bIndex, enemy.position);
                    this.enemyRows.removeEnemy(enemy, row);
                    this.score += 10;
                    this.particleManager.createParticles(enemy.position, 'explosion', 30, 0.5, 1.5);
                }
            }));
        });
    }

    bulletIntersect(bullet, enemy) {
        const bMin = bullet.position.subtract(new Vector3(bullet.size / 2, bullet.size / 2, bullet.size / 2));
        const bMax = bMin.scale(1);
        const eMin = enemy.position.subtract(new Vector3(enemy.size / 2, enemy.size / 2, enemy.size / 2));
        const eMax = eMin.scale(1);

        return (
            Math.abs(bMin.x - eMin.x) < (bMax.x + eMax.x) &&
            Math.abs(bMin.y - eMin.y) < (bMax.y + eMax.y) &&
            Math.abs(bMin.z - eMin.z) < (bMax.z + eMax.z)
        );
    }

    updateUI() {
        // Render score and lives via HTML overlay
        if (!this.font) {
            this.font = new Font('https://fonts.googleapis.com/css?family=Roboto&display=swap');
        }
        const scoreText = `Score: ${this.score}`;
        const livesText = `Lives: ${this.lives}`;

        if (!this.healthText) {
            this.healthText = document.createElement('div');
            this.healthText.style.position = 'absolute';
            this.healthText.style.top = '10px';
            this.healthText.style.left = '10px';
            this.healthText.style.color = '#0ff';
            this.healthText.style.fontFamily = 'Roboto';
            this.healthText.style.fontSize = `${this.fontSize}px`;
            this.healthText.style.background = 'rgba(0,255,255,0.5)';
            this.healthText.style.borderRadius = '8px';
            this.healthText.style.padding = '4px 12px';
            this.healthText.innerHTML = scoreText + ' | ' + livesText;
            document.body.appendChild(this.healthText);
        } else {
            this.healthText.innerHTML = scoreText + ' | ' + livesText;
        }
    }
}
