import { Vector3 } from '../shared/utils/vector3.js';
import { MeshStandardMaterial } from 'three';

export class PlayerShip {
    constructor(camera) {
        this.position = new Vector3(0, 0, -5);
        this.velocity = new Vector3(0, 0, 0);
        this.size = 1;
        this.shooting = false;
        this.shootCooldown = 0;
        this.shootDelay = 0.2; // seconds
        this.speed = 3;
        this.bulletSize = 0.2;
        this.shootPower = 1;
        this.camera = camera;
        this.mesh = this.createMesh();
        this.dispose = () => {
            if (this.mesh) this.mesh.dispose();
        };
    }

    createMesh() {
        const geometry = new THREE.BoxGeometry(this.size, this.size, this.size);
        const material = new MeshStandardMaterial({ color: 0x00aaff, roughness: 0.3, metalness: 0.7 });
        const mesh = new THREE.Mesh(geometry, material);
        mesh.castShadow = true;
        return mesh;
    }

    update(delta) {
        // Movement
        this.position.add(this.velocity.clone().multiplyScalar(delta));
        this.position.y += (this.shooting ? 0.5 : 0) * delta; // slight upward jump on shoot

        // Shoot cooldown
        if (this.shootCooldown > 0) {
            this.shootCooldown -= delta;
        }
    }

    fireBullet(position) {
        if (this.shootCooldown <= 0) {
            const bullet = new Bullet(position, this.bulletSize, this.shootPower);
            // Add to particle manager
            this.shootCooldown = this.shootDelay;
        }
    }

    get position() { return this.position; }
}
