export class Bullet {
    constructor(position, size, power) {
        this.position = new Vector3(...position);
        this.size = size;
        this.power = power;
        this.velocity = new Vector3(0, 0, -2).multiplyScalar(power * 1.5);
        this.disposed = false;
        this.mesh = this.createMesh();
