import { Vector3 } from '../shared/utils/vector3.js';
import { MeshStandardMaterial } from 'three';

export class Enemy {
    constructor(x, y, size, speed) {
        this.position = new Vector3(x, y, 0);
        this.size = size;
        this.speed = speed;
        this.velocity = new Vector3(0, 0, 0);
        this.shootCooldown = 0;
        this.shootDelay = 2 + Math.random() * 1.5;
        this.mesh = this.createMesh();
    }

    createMesh() {
        const geometry = new THREE.BoxGeometry(this.size, this.size, this.size);
        const material = new MeshStandardMaterial({ color: 0xff0000, roughness: 0.8, metalness: 0.4 });
        const mesh = new THREE.Mesh(geometry, material);
        mesh.castShadow = true;
        return mesh;
    }

    update(delta) {
        // Horizontal oscillation
        this.velocity.x = Math.sin(this.position.z * 0.5 + Date.now() * 0.01) * 1.2;
        // Forward movement
        this.position.z += this.speed * delta;
        // Keep within bounds
        const maxZ = this.mesh.canvas.parent.canvas.height / 2 - this.size / 2;
        if (this.position.z > maxZ) this.position.z = maxZ;
        if (this.position.z < -maxZ) this.position.z = -maxZ;
    }

    get position() { return this.position; }
}
