import { MeshStandardMaterial } from 'three';
import { UnrealBloomPass } from '../shared/effects/unrealBloomPass.js';

export class ParticleManager {
    constructor(renderer, camera) {
        this.renderer = renderer;
        this.camera = camera;
        this.particles = [];
        this.bulletBursts = [];
        this.particleSystem = null;
        this.bloom = new UnrealBloomPass(
            renderer.getCamera(),
            THREE.FOG_EXP2,
            1,
            0.4,
            0.85
        );
        this.bloom.energy = 1.5;
        this.bloom.threshold = 0.7;
        this.bloom.radius = 0.35;
        renderer.renderer.addPass(this.bloom);
    }

    addParticle(position, color, size, life, velocity) {
        const geometry = new THREE.SphereGeometry(size, 8, 8);
        const material = new MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.9 });
        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.copy(position);
        this.particles.push({ mesh, velocity, life, maxLife: life });
    }

    burstBullet(bulletIndex, position) {
        // Create small burst
        for (let i = 0; i < 30; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = 3 + Math.random() * 1.5;
            const vel = new THREE.Vector3(
                Math.cos(angle) * speed,
                Math.sin(angle) * speed,
                0
            ).multiplyScalar(0.7);
            this.addParticle(position, new THREE.Color(0.8, 1, 1), 0.15, 1 + Math.random(), vel);
        }
    }

    update(delta, player, enemyRows) {
        // Update particles
        this.particles.forEach(p => {
            p.mesh.position.add(p.velocity.clone().multiplyScalar(delta));
            p.life -= delta;
            if (p.life <= 0) {
                this.particles = this.particles.filter(x => x !== p);
                if (p.mesh) p.mesh.dispose();
            }
        });

        // Remove off-screen
        this.particles = this.particles.filter(p => p.mesh.position.distanceTo(this.camera.position) < 30);

        // Render particles
        if (this.particles.length > 0) {
            const geometry = new THREE.BufferGeometry();
            const positions = [];
            this.particles.forEach(p => positions.push(p.mesh.position.x, p.mesh.position.y, p.mesh.position.z));
            geometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(positions), 3));
            const material = new THREE.PointsMaterial({ color: 0xffffff, size: 0.05, transparent: true });
            if (this.particleSystem) this.particleSystem.setGeometry(geometry);
            else {
                this.particleSystem = new THREE.Points(geometry, material);
                this.renderer.scene.add(this.particleSystem);
            }
            this.particleSystem.material.needsUpdate = true;
        }

        // Handle bullet impacts
        enemyRows.forEach(row => row.enemies.forEach(enemy => {
            this.particles.forEach(p => {
                if (p.mesh && p.mesh.position.distanceTo(enemy.position) < enemy.size / 2 + p.mesh.size / 2) {
                    p.mesh.dispose();
                    p.mesh = null;
                }
            });
        }));
    }

    dispose() {
        if (this.particleSystem) {
            this.particleSystem.geometry.dispose();
            this.particleSystem.material.dispose();
            this.particleSystem = null;
        }
        if (this.bloom) this.bloom.dispose();
    }
}
