import { PlayerShip } from '../player.js';

export class InputHandler {
    constructor(player, enemyRows, particleManager) {
        this.player = player;
        this.enemyRows = enemyRows;
        this.particleManager = particleManager;
        this.keys = {};
        this.gameOver = false;
        this.bindings = {
            'w': () => { this.player.moving = true; },
            'a': () => { this.player.moving = true; },
            's': () => { this.player.moving = false; },
            'd': () => { this.player.moving = true; },
            ' ': () => { this.player.fireBullet(this.player.position); },
            'space': () => { this.player.fireBullet(this.player.position); }
        };
    }

    bindKey(key, callback) {
        this.keys[key] = false;
        window.addEventListener('keydown', e => {
            if (this.keys[key]) callback();
        });
        window.addEventListener('keyup', e => {
            if (!this.keys[key]) callback();
        });
    }

    bindGamepad() {
        if ('Gamepad' in window) {
            const gp = window.Gamepad;
            gp.onconnect = () => this.player.fireBullet(this.player.position);
            gp.onstart = () => this.player.fireBullet(this.player.position);
        }
    }

    getKeyDown(key) {
        return this.keys[key] || false;
    }

    getKeyUp(key) {
        return !this.keys[key];
    }

    isPressed(key) {
        return this.getKeyDown(key);
    }

    bindKeyboard(callback) {
        window.addEventListener('keydown', e => callback(e));
    }

    bindGamepad() {
        this.bindGamepad();
    }
}
