import { MeshStandardMaterial } from 'three';

export class ShockwavePass {
    constructor(camera, radius, intensity) {
        this.camera = camera;
        this.radius = radius;
        this.intensity = intensity;
    }

    update(delta, player, enemyRows, particleManager) {
        // Emit shockwave on impact
        const now = Date.now();
        if (player.shooting && Math.random() < 0.3) {
            const wave = new THREE.Mesh(
                new THREE.SphereGeometry(this.radius, 32, 32),
