        const baseX = -6 + Math.random() * 2;
        this.rows.push(new Row(baseX, rowCount, perRow, this.speed, this.offset));
        this.offset += Math.random() * 0.5 - 0.25;
    }

    update(delta) {
        this.rows.forEach(row => row.update(delta));
    }
}

class Row {
    constructor(baseX, rowCount, perRow, speed, offset) {
        this.baseX = baseX;
        this.enemies = [];
        this.speed = speed;
        this.oscillation = 0;
        this.offset = offset;
        this.rowCount = rowCount;
        this.enemySize = 1;
        this.generate(rowCount, perRow);
    }

    generate(count, perRow) {
        const noiseScale = 0.05;
        for (let i = 0; i < count; i++) {
            const x = this.baseX + noiseScale * Math.sin(i * 0.3 + this.oscillation) + this.offset;
            const y = -2 + Math.random() * 0.2; // fixed height
            const enemy = new Enemy(x, y, this.enemySize, this.speed);
            this.enemies.push(enemy);
        }
    }

    update(delta) {
        this.enemies.forEach(enemy => enemy.update(delta));
        this.oscillation += 0.02 * delta;
    }
}

