export class CameraShakePass {
    constructor(camera, maxStrength, maxDuration) {
        this.camera = camera;
        this.maxStrength = maxStrength;
        this.maxDuration = maxDuration;
        this.oscillation = 0;
        this.duration = 0;
        this.active = false;
    }

    update(delta) {
        if (!this.active) return;
        this.oscillation += (Math.random() - 0.5) * 0.1;
        const intensity = Math.min(this.maxStrength, this.oscillation * this.maxStrength);
        this.duration -= delta;
        if (this.duration <= 0) {
            this.active = false;
            return;
        }
        this.camera.position.x += (Math.random() - 0.5) * intensity * delta;
        this.camera.position.z += (Math.random() - 0.5) * intensity * delta;
    }

    enable() {
        this.active = true;
        this.duration = this.maxDuration;
